'use strict';
/* 픽스처 — «다른 파일»에 사는 생산자 셋. 돌아가지 않는다(파싱 재료다 · `.test.js` 를 안 붙인 이유).
 *
 * 왜 이 묶음이 따로 있나 (2026-08-14 · 4차 조임):
 *   계수기는 원문 생산자를 **지역 선언**에서만 찾았다. 그래서 상대경로 require 로 들여온
 *   생산자는 영영 안 보였고, 그것을 받은 변수가 원문변수로 못 서서 그 파일의 부정 단언이
 *   통째로 ❔모름으로 샜다(as 실측: `engineSource` 직접 17자리 + 파생까지 ~48자리).
 *   여기서 재는 것은 «한 겹 따라가는가» 하나다 — 옛 픽스처(`가드계수/`)의 ㉡축 census 는
 *   건드리지 않는다(한 픽스처에 두 축을 섞으면 어느 축이 깨졌는지 안 보인다).
 */

const fs = require('fs');

/** 이 묶음의 «공용 통로» 노릇 — 아래 `깨끗이` 가 이걸 거쳐 정제로 서야 한다. */
function 주석없이(s) {
  return s.replace(/\/\*[\s\S]*?\*\//g, ' ').replace(/(^|[^:])\/\/[^\n]*/g, '$1 ');
}

/** ① 원문 «그대로» 내준다 — as 의 `engineSource()` 모양(엔진 7파일을 읽어 이어 붙인다). */
function 엔진원문() {
  return ['a.js', 'b.js'].map((f) => fs.readFileSync(f, 'utf8')).join('\n');
}

/** ② 읽지만 «구조»를 내준다 — talk 의 `세우기()` 모양(모듈 객체다).
 *  🔴 원문으로 세면 그 팩에서 나온 데이터가 전부 원문 파생이 되고, 처방이
 *     「모듈 객체를 주석 제거기로 감싸라」가 된다 — 따를 수 없는 처방은 우회를 정상 통로로
 *     만든다(F103). 4차 조임의 «첫 판»이 정확히 여기서 틀려 talk 에 오탐 3건을 냈다. */
function 모듈세우기(경로) {
  const 원문 = fs.readFileSync(경로, 'utf8');
  const mod = { exports: {} };
  new Function('module', 원문)(mod);
  return mod.exports;
}

/** ③ 읽고서 «정제해» 내준다 — 정제가 이겨야 한다(이미 감싼 것을 또 감싸라면 안 된다). */
function 깨끗이(경로) {
  return 주석없이(fs.readFileSync(경로, 'utf8'));
}

module.exports = { 주석없이, 엔진원문, 모듈세우기, 깨끗이 };
